CREATE TABLE IF NOT EXISTS CX_ANSWER_RUBRICS (CASE_ID VARCHAR(128) NOT NULL, CASE_VERSION INTEGER NOT NULL, REVISION_NO INTEGER NOT NULL CHECK(REVISION_NO>0), RUBRIC_DIGEST VARCHAR(64) NOT NULL, RUBRIC_JSON TEXT NOT NULL, CREATED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(CASE_ID,CASE_VERSION,REVISION_NO), FOREIGN KEY(CASE_ID,CASE_VERSION) REFERENCES CX_ANSWER_EVAL_CASES(CASE_ID,VERSION));

CREATE TABLE IF NOT EXISTS CX_ANSWER_QUALITY_RUNS (RUN_ID VARCHAR(128) PRIMARY KEY, CONTINUITY_ID VARCHAR(128) NOT NULL UNIQUE REFERENCES CX_TASK_CONTINUITY_LINKS(CONTINUITY_ID), CASE_ID VARCHAR(128) NOT NULL, CASE_VERSION INTEGER NOT NULL, RUBRIC_REVISION INTEGER NOT NULL, CASE_DIGEST VARCHAR(64) NOT NULL, RUBRIC_DIGEST VARCHAR(64) NOT NULL, ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), SECURITY_DOMAIN_ID VARCHAR(128) NOT NULL REFERENCES CX_SECURITY_DOMAINS(SECURITY_DOMAIN_ID), AGENT_ID VARCHAR(128) NOT NULL REFERENCES CX_NATIVE_AGENTS(AGENT_ID), PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), POLICY_VERSION INTEGER NOT NULL CHECK(POLICY_VERSION>0), POLICY_DIGEST VARCHAR(64) NOT NULL, ENTRY_KIND VARCHAR(16) NOT NULL CHECK(ENTRY_KIND IN ('PORTAL','CHANNEL')), IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, STATUS VARCHAR(24) NOT NULL CHECK(STATUS IN ('PENDING','RUNNING','SUCCEEDED','FAILED','UNOBSERVED')), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, COMPLETED_AT TIMESTAMP, UNIQUE(ACTOR_ID,IDEMPOTENCY_KEY), FOREIGN KEY(CASE_ID,CASE_VERSION,RUBRIC_REVISION) REFERENCES CX_ANSWER_RUBRICS(CASE_ID,CASE_VERSION,REVISION_NO));

CREATE TABLE IF NOT EXISTS CX_ANSWER_QUALITY_INPUTS (RUN_ID VARCHAR(128) PRIMARY KEY REFERENCES CX_ANSWER_QUALITY_RUNS(RUN_ID), ATTEMPT_ID VARCHAR(128) NOT NULL REFERENCES CX_TASK_CONTINUITY_ATTEMPTS(ATTEMPT_ID), INPUT_CIPHER TEXT NOT NULL, INPUT_DIGEST VARCHAR(64) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_ANSWER_QUALITY_SOURCES (RUN_ID VARCHAR(128) NOT NULL REFERENCES CX_ANSWER_QUALITY_RUNS(RUN_ID), ITEM_NO INTEGER NOT NULL CHECK(ITEM_NO>0), ENTITY_ID VARCHAR(128) NOT NULL, CONTENT_DIGEST VARCHAR(64) NOT NULL, PRIMARY KEY(RUN_ID,ITEM_NO), UNIQUE(RUN_ID,ENTITY_ID));

CREATE TABLE IF NOT EXISTS CX_ANSWER_QUALITY_OUTPUTS (RUN_ID VARCHAR(128) PRIMARY KEY REFERENCES CX_ANSWER_QUALITY_RUNS(RUN_ID), ATTEMPT_ID VARCHAR(128) NOT NULL REFERENCES CX_TASK_CONTINUITY_ATTEMPTS(ATTEMPT_ID), FENCING_TOKEN INTEGER NOT NULL CHECK(FENCING_TOKEN>0), OUTPUT_CIPHER TEXT NOT NULL, OUTPUT_DIGEST VARCHAR(64) NOT NULL, MODEL_ID VARCHAR(256), GENERATION_KIND VARCHAR(24) NOT NULL CHECK(GENERATION_KIND IN ('REAL_MODEL','DETERMINISTIC')), LATENCY_MS INTEGER NOT NULL CHECK(LATENCY_MS>=0), ASSERTIONS_PASSED CHAR(1) NOT NULL CHECK(ASSERTIONS_PASSED IN ('Y','N')), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS CX_ANSWER_QUALITY_REVIEWS (RUN_ID VARCHAR(128) NOT NULL REFERENCES CX_ANSWER_QUALITY_OUTPUTS(RUN_ID), REVIEWER_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), OUTPUT_DIGEST VARCHAR(64) NOT NULL, FACTUAL_CORRECT CHAR(1) NOT NULL CHECK(FACTUAL_CORRECT IN ('Y','N')), CITATIONS_SUPPORTED CHAR(1) NOT NULL CHECK(CITATIONS_SUPPORTED IN ('Y','N')), REASON VARCHAR(1000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, PRIMARY KEY(RUN_ID,REVIEWER_ID));

